// Example test using node-fetch and Mocha
const fetch = require('node-fetch');
describe('idempotency tests', function() {
  it('duplicates are prevented with same Idempotency-Key', async function() {
    const url = 'https://api.example.com/transactions';
    const payload = {amount: 10, currency: 'USD'};
    const headers = {'Idempotency-Key': 'A'};
    const r1 = await fetch(url, {method: 'POST', headers, body: JSON.stringify(payload)});
    const r2 = await fetch(url, {method: 'POST', headers, body: JSON.stringify(payload)});
    const d1 = await r1.json();
    const d2 = await r2.json();
    if (r1.status !== 200 || r2.status !== 200 || d1.id !== d2.id) throw new Error('idempotency failed');
  });
});
``` 

